import React, { useMemo, useState } from "react";
import { GALLERY } from "./Content";

const TABS = ["All", "Weddings", "Corporate", "Parties", "Festivals"];

export default function Portfolio() {
  const [active, setActive] = useState("All");
  const items = useMemo(
    () => (active === "All" ? GALLERY : GALLERY.filter((g) => g.category === active)),
    [active]
  );

  return (
    <section id="portfolio" className="relative px-6 md:px-12 lg:px-24 py-24 md:py-32" data-testid="portfolio-section">
      <div className="flex items-end justify-between flex-wrap gap-6 mb-12">
        <div>
          <div className="overline mb-4">Portfolio</div>
          <h2 className="serif" style={{ fontSize: "clamp(36px, 5vw, 72px)", lineHeight: 1.02, fontWeight: 300, color: "#fffff0", maxWidth: 720 }}>
            Selected <span style={{ color: "#d4af37", fontStyle: "italic" }}>moments</span> we've adorned.
          </h2>
        </div>
        <div className="flex flex-wrap gap-2">
          {TABS.map((t) => (
            <button
              key={t}
              onClick={() => setActive(t)}
              className="px-5 py-2 rounded-full text-xs tracking-[0.18em] uppercase transition-all duration-300"
              style={{
                background: active === t ? "linear-gradient(135deg,#d4af37,#f7e7ce)" : "transparent",
                color: active === t ? "#1a080a" : "rgba(255,255,240,0.7)",
                border: active === t ? "1px solid transparent" : "1px solid rgba(212,175,55,0.35)",
                fontWeight: 500,
              }}
              data-testid={`portfolio-filter-${t.toLowerCase()}`}
            >
              {t}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 auto-rows-[220px] gap-4">
        {items.map((it, i) => (
          <figure
            key={`${active}-${it.src}`}
            className={`group relative overflow-hidden rounded-sm gold-border ${i % 5 === 0 ? "row-span-2" : ""} ${i % 7 === 0 ? "col-span-2" : ""}`}
            data-testid={`portfolio-item-${i}`}
            style={{ animation: `fadeUp 600ms ease ${i * 40}ms both` }}
          >
            <img src={it.src} alt={it.title} loading="lazy" className="absolute inset-0 w-full h-full object-cover transition-transform duration-1000 group-hover:scale-110" />
            <div className="absolute inset-0" style={{ background: "linear-gradient(180deg, rgba(13,4,5,0) 40%, rgba(13,4,5,0.85) 100%)" }} />
            <figcaption className="absolute bottom-3 left-4 right-4">
              <div className="overline" style={{ color: "#d4af37", letterSpacing: "0.22em" }}>{it.category}</div>
              <div className="serif" style={{ color: "#fffff0", fontSize: 18, marginTop: 4 }}>{it.title}</div>
            </figcaption>
          </figure>
        ))}
      </div>

      <style>{`
        @keyframes fadeUp {
          from { opacity: 0; transform: translateY(20px) }
          to   { opacity: 1; transform: translateY(0) }
        }
      `}</style>
    </section>
  );
}
